<script src="viewer_data.json" type="application/json" id="__unused"></script>
<script>
  const STATUS_COLS = new Set([
    "Status", "Stage", "Outcome", "Recommendation", "Rejection Reason", "Role"
  ]);
  const PILL_MAP = {
    // Applications.Status / Stage
    "Open": "good", "Closed": "neutral", "Rejected": "bad", "Hired": "good", "Withdrawn": "neutral",
    "Applied": "neutral", "Screened": "neutral", "Interviewing": "warn", "Offer": "warn",
    // Job Openings.Status
    "Filled": "good", "On Hold": "warn", "Cancelled": "bad",
    // Interviews.Outcome / Recommendation
    "Completed": "good", "Scheduled": "warn", "Cancelled ": "bad", "No Show": "bad",
    "Strong Hire": "good", "Hire": "good", "No Hire": "bad", "Strong No Hire": "bad",
    // Offers.Status
    "Accepted": "good", "Pending": "warn", "Declined": "bad", "Rescinded": "bad", "Expired": "neutral",
  };
  const NUM_COLS = new Set([
    "Expected CTC", "Current CTC", "Notice Period Days", "Years Experience",
    "Headcount Budget", "Headcount", "Salary Band Min", "Salary Band Max",
    "Score", "Base CTC", "Joining Bonus"
  ]);
  const ID_COLS = new Set(["Record ID", "Candidate ID", "Application ID", "Interview ID", "Offer ID", "Req ID", "Code"]);

  let DATA = null;
  let currentSlug = null;
  let sortState = { col: null, dir: 1 };

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function renderNav() {
    const nav = document.getElementById('tableNav');
    nav.innerHTML = '';
    Object.entries(DATA).forEach(([slug, t]) => {
      const btn = document.createElement('button');
      btn.className = 'tab-btn' + (slug === currentSlug ? ' active' : '');
      btn.innerHTML = `<span>${t.display}</span><span class="count">${t.rows.length}</span>`;
      btn.addEventListener('click', () => selectTable(slug));
      nav.appendChild(btn);
    });
    const total = Object.values(DATA).reduce((a, t) => a + t.rows.length, 0);
    document.getElementById('railFoot').textContent = `${total} records total · pulled ${new Date().toISOString().slice(0,10)}`;
  }

  function selectTable(slug) {
    currentSlug = slug;
    sortState = { col: null, dir: 1 };
    document.getElementById('search').value = '';
    renderNav();
    renderTable();
  }

  function cellClass(col) {
    if (ID_COLS.has(col)) return 'id';
    if (NUM_COLS.has(col)) return 'num';
    return '';
  }

  function formatCell(col, val) {
    if (val === '' || val === null || val === undefined) return '<span style="color:var(--ink-faint)">—</span>';
    if (STATUS_COLS.has(col)) {
      const kind = PILL_MAP[val] || 'neutral';
      return `<span class="pill ${kind}">${escapeHtml(val)}</span>`;
    }
    if (NUM_COLS.has(col) && typeof val === 'number') {
      return val.toLocaleString('en-IN');
    }
    return escapeHtml(val);
  }

  function renderTable() {
    const t = DATA[currentSlug];
    document.getElementById('tableTitle').textContent = t.display;
    document.getElementById('tableSub').textContent = `${t.rows.length} records · ${t.columns.length} fields`;

    const q = document.getElementById('search').value.trim().toLowerCase();
    let rows = t.rows;
    if (q) {
      rows = rows.filter(r => t.columns.some(c => String(r[c] ?? '').toLowerCase().includes(q)));
    }
    if (sortState.col) {
      const c = sortState.col;
      rows = [...rows].sort((a, b) => {
        let av = a[c], bv = b[c];
        if (typeof av === 'number' && typeof bv === 'number') return (av - bv) * sortState.dir;
        av = String(av ?? ''); bv = String(bv ?? '');
        return av.localeCompare(bv) * sortState.dir;
      });
    }

    const scroll = document.getElementById('tableScroll');
    if (t.rows.length === 0) {
      scroll.innerHTML = `<div class="empty-state">No records in this table. (Findings is the write-back table — expected empty on a read-only pull.)</div>`;
      return;
    }

    let html = '<table><thead><tr>';
    t.columns.forEach(c => {
      const arrow = sortState.col === c ? (sortState.dir === 1 ? '↑' : '↓') : '';
      html += `<th class="${cellClass(c)}" data-col="${escapeHtml(c)}">${escapeHtml(c)}<span class="arrow">${arrow}</span></th>`;
    });
    html += '</tr></thead><tbody>';
    rows.forEach(r => {
      html += '<tr>';
      t.columns.forEach(c => {
        html += `<td class="${cellClass(c)}">${formatCell(c, r[c])}</td>`;
      });
      html += '</tr>';
    });
    html += '</tbody></table>';
    scroll.innerHTML = html;

    scroll.querySelectorAll('th').forEach(th => {
      th.addEventListener('click', () => {
        const col = th.dataset.col;
        if (sortState.col === col) sortState.dir *= -1;
        else { sortState.col = col; sortState.dir = 1; }
        renderTable();
      });
    });
  }

  document.getElementById('search').addEventListener('input', renderTable);

  fetch('viewer_data.json').then(r => r.json()).then(json => {
    DATA = json;
    currentSlug = Object.keys(DATA)[0];
    renderNav();
    renderTable();
  });
</script>

</body></html>

