python3 - <<'EOF'
import json
cands = {r['id']: r['fields'] for r in json.load(open('candidates.json'))}
apps = {r['id']: r['fields'] for r in json.load(open('applications.json'))}
offers = json.load(open('offers.json'))

from collections import Counter, defaultdict

# candidate-level: did this candidate end up hired (any Hired application)?
cand_hired = set()
for aid, af in apps.items():
    if af.get('Stage') == 'Hired':
        for cid in af.get('Candidate', []):
            cand_hired.add(cid)

cand_total_by_source = Counter()
cand_hired_by_source = Counter()
for cid, cf in cands.items():
    src = cf.get('Source', 'UNKNOWN')
    cand_total_by_source[src] += 1
    if cid in cand_hired:
        cand_hired_by_source[src] += 1

print("Candidate-level conversion by source (hired candidates / sourced candidates):")
for src in cand_total_by_source:
    tot = cand_total_by_source[src]
