  const PENDING_FAIL = "Offer acceptance rate. Offers still waiting for a decision are counted as NOT accepted.";
  const PENDING_EXCL = "Offer acceptance rate. Offers still waiting for a decision are left out of the count entirely.";
  const find = (what, group) => h.find(r => r['What this row shows'] === what && r['Source / Group'] === group);

  const pFail = find(PENDING_FAIL, 'All offers');
  const pExcl = find(PENDING_EXCL, 'All offers');
  const jbDedup = find(DEDUP_SHARE, 'Job Board');
  const jbRaw = find(RAW_SHARE, 'Job Board');
  const mat = DATA.materiality_summary.find(r => r.Issue.startsWith('TOTAL'));
  const overdue = DATA.requisition_aging.filter(r => r.Status === 'Open' && r['Is it overdue?'] === 'True');
  const open = DATA.requisition_aging.filter(r => r.Status === 'Open');
  const rakesh = DATA.interviewer_calibration.find(r => r.Interviewer === 'Rakesh Sethi');
  const noHireCount = Number(rakesh["Said 'No Hire'"]) + Number(rakesh["Said 'Strong No Hire'"]);

  let html = '';
  html += '<p class="lede">This page shows the numbers behind two questions the VP of People asked, plus a few problems the data turned up on its own. Six boxes below. Each one names the number, what it is out of, and one sentence on what it means.</p>';
  html += '<div class="summary-grid">';

  html += statCard(
    'Question 1: How many offers get accepted?',
    pFail.Percentage + '%',
    `This is ${pFail['Count (top number)']} accepted out of ${pFail['Total counted']} offers. The true number is probably between ${pFail['Low end of likely range (95%)']}% and ${pFail['High end of likely range (95%)']}%.`,
    'This counts an offer that nobody has decided on yet as a "no."'
  );
  html += statCard(
    'Question 1, counted a different way',
    pExcl.Percentage + '%',
    `Same offers, but this time the ${pFail['Total counted'] - pExcl['Total counted']} still-undecided offers are left out completely, not counted as a "no." Likely range: ${pExcl['Low end of likely range (95%)']}% to ${pExcl['High end of likely range (95%)']}%.`,
    'These two boxes overlap. With only 36 offers total, we cannot tell which one is more correct — see the metric spec doc for the fix.'
  );
  html += statCard(
    'Question 2: Is Job Board really the top source of hires?',
    jbDedup.Percentage + '%',
    `Job Board produced ${jbDedup.Percentage}% of all hires once we merged duplicate candidate records. Before that fix it looked like ${jbRaw.Percentage}%, tied with Referral.`,
    'Yes, Job Board is the top source. It also has the worst hire rate per candidate of any source (see the Source x Stage table).'
  );
  html += statCard(
    'A problem nobody asked about: overdue job openings',
    overdue.length + ' out of ' + open.length,
    `${overdue.length} of the ${open.length} job openings that are still open have already passed their own target close date. Some by over a year.`,
    'This was not part of either question the VP asked. It is the single largest problem found in this data.',
    true
  );
  html += statCard(
    'How much of the data has an error in it',
    mat['Records affected'] + ' out of ' + mat['Total records in that table (or in the whole dataset for the last row)'],
    `${mat['Share affected (%)']}% of all records pulled have at least one of five problems we checked for (duplicate people, reused ID numbers, a status field that did not update, and two cases of an end date coming before a start date).`,
    'Small in total, but concentrated in exactly the records both VP questions depend on. Full list in the data quality audit doc.'
  );
  html += statCard(
    'One interviewer whose opinion does not match the outcome',
    'Rakesh Sethi',
    `He told ${noHireCount} of his ${rakesh['Total interviews given']} candidates "no" or "strong no." 9 of those people were hired anyway or are still in the running for an offer.`,
    'This is a training or reassignment conversation, not something engineering can fix.',
    true
  );
  html += '</div>';
  html += '<h3 class="section-title">Where to read more</h3><p class="lede">Use the menu on the left to see the full table behind any of these numbers. The complete write-up — what we recommend building, what we recommend not building, and why — is in two documents: <code>docs/strategy/talentflow-q3-roadmap.md</code> and <code>docs/discovery/talentflow-data-quality-audit.md</code>.</p>';
  return html;
}

