import json
from datetime import date

def pd(s):
    if not s: return None
    y,m,d = s.split('-')
    return date(int(y),int(m),int(d))

apps = json.load(open('applications.json'))
openings = {r['id']: r['fields'] for r in json.load(open('job_openings.json'))}
cands = {r['id']: r['fields'] for r in json.load(open('candidates.json'))}

withdrawn = [a['fields'] for a in apps if a['fields'].get('Stage')=='Withdrawn']
print(f"Total withdrawn: {len(withdrawn)}")

by_level = {}
for f in withdrawn:
    op = (f.get('Opening') or [None])[0]
    level = openings.get(op, {}).get('Level') if op else None
    by_level.setdefault(level, []).append(f)

for level, fl in by_level.items():
    days = []
    ctc_gaps = []
    notice = []
    for f in fl:
        applied, closed = pd(f.get('Applied On')), pd(f.get('Closed On'))
        if applied and closed:
            days.append((closed-applied).days)
        cid = (f.get('Candidate') or [None])[0]
        cf = cands.get(cid, {})
        exp, cur = cf.get('Expected CTC'), cf.get('Current CTC')
        if exp and cur:
            ctc_gaps.append(round((exp-cur)/cur*100,1))
        if cf.get('Notice Period Days') is not None:
            notice.append(cf.get('Notice Period Days'))
    print(f"\nLevel={level}, n={len(fl)}")
    print(f"  days applied->withdrawn: {sorted(days)}")
    print(f"  CTC ask gap %: {sorted(ctc_gaps)}")
    print(f"  notice period days: {sorted(notice)}")

print("\n=== For comparison: same stats for Rejected (not withdrawn) by level ===")
rejected = [a['fields'] for a in apps if a['fields'].get('Stage')=='Rejected']
by_level_r = {}
for f in rejected:
    op = (f.get('Opening') or [None])[0]
    level = openings.get(op, {}).get('Level') if op else None
    by_level_r.setdefault(level, []).append(f)
for level, fl in by_level_r.items():
    print(f"  Level={level}: n rejected={len(fl)}")
EOF

