import json
apps = json.load(open('applications.json'))
openings = {r['id']: r['fields'] for r in json.load(open('job_openings.json'))}
cands = {r['id']: r['fields'] for r in json.load(open('candidates.json'))}

def ctc_gap(cid):
    cf = cands.get(cid, {})
    exp, cur = cf.get('Expected CTC'), cf.get('Current CTC')
    if exp and cur:
        return round((exp-cur)/cur*100,1)
    return None

for stage in ['Hired', 'Withdrawn', 'Rejected']:
    gaps = []
    for a in apps:
        f = a['fields']
        op = (f.get('Opening') or [None])[0]
        level = openings.get(op, {}).get('Level') if op else None
        if level != 'Senior' or f.get('Stage') != stage: continue
        cid = (f.get('Candidate') or [None])[0]
        g = ctc_gap(cid)
        if g is not None: gaps.append(g)
    if gaps:
        print(f"Senior, Stage={stage}: n={len(gaps)}, median CTC ask gap={sorted(gaps)[len(gaps)//2]}%, avg={sum(gaps)/len(gaps):.1f}%")
EOF

python3 - <<'EOF'
import json
from datetime import date
from statistics import median

def pd(s):
    if not s: return None
    y,m,d = s.split('-')
    return date(int(y),int(m),int(d))

apps = json.load(open('applications.json'))
openings = {r['id']: r['fields'] for r in json.load(open('job_openings.json'))}

by_level = {}
for a in apps:
    f = a['fields']
    if f.get('Status') != 'Closed': continue
    op = (f.get('Opening') or [None])[0]
    level = openings.get(op, {}).get('Level') if op else None
    applied, closed = pd(f.get('Applied On')), pd(f.get('Closed On'))
    if applied and closed:
        by_level.setdefault(level, []).append((closed-applied).days)

for level, days in by_level.items():
    print(f"Level={level}: n={len(days)}, median days to close={median(days)}")

print("\n=== Withdrawal rate by level (withdrawn / total applications at that level) ===")
level_totals = {}
level_withdrawn = {}
for a in apps:
    f = a['fields']
    op = (f.get('Opening') or [None])[0]
    level = openings.get(op, {}).get('Level') if op else None
    level_totals[level] = level_totals.get(level,0)+1
    if f.get('Stage')=='Withdrawn':
        level_withdrawn[level] = level_withdrawn.get(level,0)+1
for level in level_totals:
    w = level_withdrawn.get(level,0)
    print(f"  {level}: {w}/{level_totals[level]} = {w/level_totals[level]*100:.1f}%")
EOF

