function renderTable(rows) {
  if (!rows.length) return '<div style="padding:40px;color:var(--ink-faint)">No rows.</div>';
  const cols = Object.keys(rows[0]);
  let html = '<div class="table-wrap"><table><thead><tr>';
  cols.forEach(c => html += `<th>${esc(c)}</th>`);
  html += '</tr></thead><tbody>';
  rows.forEach(r => {
    html += '<tr>';
    cols.forEach(c => {
      let v = r[c];
      const vLower = String(v).toLowerCase();
      const isNum = v !== '' && !isNaN(v) && v !== null;
      if (v === 'True' || v === 'False' || vLower === 'yes' || vLower === 'no') {
        const norm = (v === 'True' || vLower === 'yes') ? 'yes' : 'no';
        html += `<td><span class="pill ${norm}">${esc(v)}</span></td>`;
      } else {
        html += `<td class="${isNum ? 'num' : ''}">${esc(v ?? '')}</td>`;
      }
    });
    html += '</tr>';

