cd /Users/rishabrawat/pm/talentflow/data && python3 - <<'EOF'
import json
apps = json.load(open('applications.json'))
interviews = json.load(open('interviews.json'))
cands = {r['id']: r['fields'] for r in json.load(open('candidates.json'))}

interviews_by_app = {}
for iv in interviews:
    for aid in iv['fields'].get('Application', []):
        interviews_by_app[aid] = interviews_by_app.get(aid, 0) + 1

# Job Board pre-interview rejections with "Culture Fit" or "Skills Mismatch"
examples = []
for a in apps:
    f = a['fields']
    if f.get('Stage') != 'Rejected':
        continue
    cid = (f.get('Candidate') or [None])[0]
    src = cands.get(cid, {}).get('Source') if cid else None
    if src != 'Job Board':
        continue
    has_iv = interviews_by_app.get(a['id'], 0) > 0
    if has_iv:
        continue
    reason = f.get('Rejection Reason')
    if reason in ('Culture Fit', 'Skills Mismatch'):
        examples.append(f)

print(f"Total pre-interview Job Board rejections with Culture Fit/Skills Mismatch: {len(examples)}")
print("\nSample fields available on these applications:")
for f in examples[:5]:
    print({k: f.get(k) for k in ['Applied On', 'Screened On', 'Closed On', 'Stage', 'Status', 'Rejection Reason']})

# Check: how many of these have a Screened On date filled?
screened = sum(1 for f in examples if f.get('Screened On'))
print(f"\nOf these, have a 'Screened On' date filled: {screened} / {len(examples)}")
EOF

